+    return forced ? { name: 'force-push', reason: 'git push that rewrites or deletes remote refs' } : undefined;
+  }
+  if (sub === 'reset' && rest.includes('--hard')) return { name: 'reset-hard', reason: 'git reset --hard discards local changes' };
+  if (sub === 'clean' && rest.some((w) => w === '--force' || hasShortFlag(w, 'f')) && !rest.some((w) => w === '-n' || w === '--dry-run'))
+    return { name: 'clean-force', reason: 'git clean -f deletes untracked files' };
+  return undefined;
+}
+
+function rmHit(args: string[], cwd: string): Hit | undefined {
+  const dd = args.indexOf('--');
+  const opts = dd < 0 ? args : args.slice(0, dd);
+  if (!opts.some((w) => w === '--recursive' || hasShortFlag(w, 'rR'))) return undefined;
+  const targets = [...opts.filter((w) => !w.startsWith('-')), ...(dd < 0 ? [] : args.slice(dd + 1))];
+  const bad = targets.length === 0 || targets.some((p) => unresolvable(p) || !insideWorkspace(p, cwd) || sameDir(p, cwd));
+  return bad ? { name: 'rm-outside', reason: 'recursive rm of a target outside the working directory, or of the working directory itself' } : undefined;
